import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * SPIKE (Routine C, no production changes): reproduces the reported shape
 *
 * <pre>
 * SELECT DISTINCT ?bbid WHERE { ?cmp a bb:Company . ?cmp bb:bbid ?bbid . ?cmp bb:educationInstitutionFor ?emp }
 * </pre>
 *
 * and times it with (a) adjacency + kernels off, (b) adjacency on / kernels off, (c) kernels on. The fan-out of the
 * root predicate is a knob so the same structure can be measured at two edge counts: a fixed cost stays put when the
 * fan-out shrinks, a per-edge cost scales with it.
 */
class ScratchStarDistinctTimingTest {

	private static final String BB = "http://bloomberg#";

	private static final int COMPANIES = Integer.getInteger("scratch.companies", 7227);
	private static final int FANOUT = Integer.getInteger("scratch.fanout", 290);
	private static final int NOISE = Integer.getInteger("scratch.noise", 300_000);
	private static final int REPEATS = Integer.getInteger("scratch.repeats", 5);

	private static final String QUERY = "prefix bb: <" + BB + "> "
			+ "select distinct ?bbid where { ?cmp a bb:Company . ?cmp bb:bbid ?bbid . ?cmp bb:educationInstitutionFor ?emp }";

	private static final String[] TOGGLES = {
			"rdf4j.lmdb.janinoCodegen.enabled",
			"rdf4j.lmdb.kernelInterpreter.enabled",
			"rdf4j.lmdb.janinoCodegen.synchronous",
			"rdf4j.lmdb.irKernelParallel.enabled",
	};

	@Test
	void timeTheThreeRegimes(@TempDir File dir) throws Exception {
		List<String[]> saved = new ArrayList<>();
		for (String key : TOGGLES) {
			saved.add(new String[] { key, System.getProperty(key) });
		}
		LmdbStoreConfig loadConfig = new LmdbStoreConfig("spoc,posc,ospc");
		loadConfig.setDirectAdjacencyMode(DirectAdjacencyMode.DISABLED);
		SailRepository loader = new SailRepository(new LmdbStore(dir, loadConfig));
		loader.init();
		try {
			load(loader);
		} finally {
			loader.shutDown();
		}

		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc");
		config.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER);
		config.setDirectAdjacencyBuildOnStart(true);
		config.setDirectAdjacencyMaxBytes(4L * 1024 * 1024 * 1024);
		LmdbStore store = new LmdbStore(dir, config);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			System.out.println("[scratch] adjacency ready: "
					+ store.awaitDirectAdjacencyReady(600, TimeUnit.SECONDS));
			System.out.println("[scratch] adjacency readiness: " + store.getDirectAdjacencyReadinessDescription());
			System.out.println("[scratch] companies=" + COMPANIES + " fanout=" + FANOUT + " noise=" + NOISE
					+ " eduEdges=" + ((long) COMPANIES * FANOUT));

			String only = System.getProperty("scratch.only", "all");

			if (only.equals("all") || only.equals("off")) {
				// (a) kernels off
				System.setProperty("rdf4j.lmdb.janinoCodegen.enabled", "false");
				System.setProperty("rdf4j.lmdb.kernelInterpreter.enabled", "false");
				run(repository, "adjacency=PREFER kernels=off");
			}

			if (only.equals("all") || only.equals("par")) {
				// (c) compiled kernels on, synchronous compile so timings are not a compile race
				System.setProperty("rdf4j.lmdb.janinoCodegen.enabled", "true");
				System.setProperty("rdf4j.lmdb.kernelInterpreter.enabled", "true");
				System.setProperty("rdf4j.lmdb.janinoCodegen.synchronous", "true");
				run(repository, "adjacency=PREFER kernels=on(sync)");
			}

			if (only.equals("all") || only.equals("fact")) {
				// kernels off AND packedFtree off: forces the factorizedRows rung the reported 0.4s run picked
				System.setProperty("rdf4j.lmdb.janinoCodegen.enabled", "false");
				System.setProperty("rdf4j.lmdb.kernelInterpreter.enabled", "false");
				System.setProperty("rdf4j.lmdb.packedFtree.enabled", "false");
				run(repository, "adjacency=PREFER kernels=off packedFtree=off");
				System.clearProperty("rdf4j.lmdb.packedFtree.enabled");
			}

			if (only.equals("all") || only.equals("seq")) {
				// (c2) kernels on but the parallel kernel rung off — isolates the kernel's own per-key cost
				System.setProperty("rdf4j.lmdb.janinoCodegen.enabled", "true");
				System.setProperty("rdf4j.lmdb.kernelInterpreter.enabled", "true");
				System.setProperty("rdf4j.lmdb.janinoCodegen.synchronous", "true");
				System.setProperty("rdf4j.lmdb.irKernelParallel.enabled", "false");
				run(repository, "adjacency=PREFER kernels=on parallelKernel=off");
				System.setProperty("rdf4j.lmdb.irKernelParallel.enabled", "true");
			}
		} finally {
			try {
				repository.shutDown();
			} finally {
				for (String[] entry : saved) {
					if (entry[1] == null) {
						System.clearProperty(entry[0]);
					} else {
						System.setProperty(entry[0], entry[1]);
					}
				}
			}
		}
	}

	/** Poor-man's sampling profiler over the query thread; -DargLine does not reach the surefire fork here. */
	private static Thread startSampler(Thread target, java.util.Map<String, Integer> leaves,
			java.util.Map<String, Integer> frames, java.util.concurrent.atomic.AtomicBoolean stop) {
		Thread sampler = new Thread(() -> {
			while (!stop.get()) {
				StackTraceElement[] trace = target.getStackTrace();
				if (trace.length > 0) {
					String leaf = trace[0].getClassName() + "." + trace[0].getMethodName();
					leaves.merge(leaf, 1, Integer::sum);
					StringBuilder path = new StringBuilder();
					int kept = 0;
					for (StackTraceElement element : trace) {
						String cls = element.getClassName();
						if (!cls.startsWith("org.eclipse.rdf4j")
								|| cls.startsWith("org.eclipse.rdf4j.sail.lmdb.evaluation.Scratch")) {
							continue;
						}
						if (kept++ > 0) {
							path.append("\n[scratch-prof]        <- ");
						}
						path.append(cls.substring(cls.lastIndexOf('.') + 1))
								.append('.')
								.append(element.getMethodName())
								.append(':')
								.append(element.getLineNumber());
						if (kept >= 14) {
							break;
						}
					}
					if (kept > 0) {
						frames.merge(path.toString(), 1, Integer::sum);
					}
				}
				try {
					Thread.sleep(1);
				} catch (InterruptedException e) {
					return;
				}
			}
		}, "scratch-sampler");
		sampler.setDaemon(true);
		sampler.start();
		return sampler;
	}

	private static void report(String title, java.util.Map<String, Integer> counts, int limit) {
		System.out.println("[scratch-prof] " + title);
		counts.entrySet()
				.stream()
				.sorted((a, b) -> Integer.compare(b.getValue(), a.getValue()))
				.limit(limit)
				.forEach(e -> System.out.println("[scratch-prof]   " + e.getValue() + "  " + e.getKey()));
	}

	private void run(SailRepository repository, String label) { // prints timings then the executed plan
		long best = Long.MAX_VALUE;
		long rows = -1;
		java.util.Map<String, Integer> leaves = new java.util.concurrent.ConcurrentHashMap<>();
		java.util.Map<String, Integer> frames = new java.util.concurrent.ConcurrentHashMap<>();
		java.util.concurrent.atomic.AtomicBoolean stop = new java.util.concurrent.atomic.AtomicBoolean();
		startSampler(Thread.currentThread(), leaves, frames, stop);
		for (int i = 0; i < REPEATS; i++) {
			long start = System.nanoTime();
			long count = 0;
			try (SailRepositoryConnection connection = repository.getConnection();
					TupleQueryResult result = connection.prepareTupleQuery(QUERY).evaluate()) {
				while (result.hasNext()) {
					result.next();
					count++;
				}
			}
			long elapsed = System.nanoTime() - start;
			rows = count;
			best = Math.min(best, elapsed);
			System.out.println("[scratch] " + label + " run " + i + " = "
					+ TimeUnit.NANOSECONDS.toMillis(elapsed) + " ms (" + count + " rows)");
		}
		stop.set(true);
		System.out.println("[scratch] === " + label + " best=" + TimeUnit.NANOSECONDS.toMillis(best) + " ms rows="
				+ rows);
		report("LEAF frames -- " + label, leaves, 25);
		report("STACK paths -- " + label, frames, 8);
		System.out.println("[scratch-plan] >>>>>>>>>> " + label);
		System.out.println(plan(repository));
		System.out.println("[scratch-plan] <<<<<<<<<< " + label);
	}

	private String plan(SailRepository repository) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			TupleQuery query = connection.prepareTupleQuery(QUERY);
			Explanation explanation = query.explain(Explanation.Level.Telemetry);
			return explanation.toString();
		}
	}

	private void load(SailRepository repository) {
		ValueFactory vf = SimpleValueFactory.getInstance();
		IRI company = vf.createIRI(BB, "Company");
		// (unused since noise is typed Company)
		IRI bbid = vf.createIRI(BB, "bbid");
		IRI edu = vf.createIRI(BB, "educationInstitutionFor");
		long start = System.nanoTime();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin();
			long added = 0;
			for (int c = 0; c < COMPANIES; c++) {
				IRI subject = vf.createIRI(BB, "cmp" + c);
				connection.add(subject, org.eclipse.rdf4j.model.vocabulary.RDF.TYPE, company);
				connection.add(subject, bbid, vf.createLiteral("BBID-" + c));
				for (int e = 0; e < FANOUT; e++) {
					connection.add(subject, edu, vf.createIRI(BB, "emp" + (c * FANOUT + e)));
					if (++added % 500_000 == 0) {
						connection.commit();
						connection.begin();
					}
				}
			}
			// Background companies with no edu edges: this makes the bb:Company extent much larger than the edu
			// predicate, which is what makes the planner root the join at edu (as in the reported plan).
			for (int n = 0; n < NOISE; n++) {
				IRI subject = vf.createIRI(BB, "noise" + n);
				connection.add(subject, org.eclipse.rdf4j.model.vocabulary.RDF.TYPE, company);
				connection.add(subject, bbid, vf.createLiteral("NOISE-" + n));
				if (++added % 500_000 == 0) {
					connection.commit();
					connection.begin();
				}
			}
			connection.commit();
		}
		System.out.println("[scratch] load took " + TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - start) + " ms");
	}
}
